  function educationHtml(item){if(!item)return'<section class="method-learning learning-missing"><h4>방법론 쉽게 이해하기</h4><p>교육 자료를 불러오지 못했습니다. 계산 결과와는 무관하며 연결 뒤 다시 확인할 수 있습니다.</p></section>';var masters=item.masters||[],caseStudy=item.caseStudy||{};return'<section class="method-learning" aria-labelledby="learning-'+escapeHtml(item.id)+'"><div class="learning-heading"><span class="learning-kicker">METHOD EXPLAINER</span><h4 id="learning-'+escapeHtml(item.id)+'">이 방법, 쉽게 이해하기</h4></div><div class="quick-explanation"><b>30초 설명</b><p>'+escapeHtml(item.shortExplanationKo)+'</p></div><div class="analogy-box"><b>직관적인 비유</b><p>'+escapeHtml(item.analogyKo)+'</p></div><details class="learning-details"><summary>작동 원리·필요 자료·적합 환경</summary><p>'+escapeHtml(item.principleKo)+'</p><h5>계산 순서</h5><ol>'+item.stepsKo.map(function(step){return'<li>'+escapeHtml(step)+'</li>';}).join('')+'</ol><h5>필요한 자료</h5>'+list(item.requiredDataKo)+'<h5>잘 맞기 쉬운 환경</h5><p>'+escapeHtml(item.favorableMarketKo)+'</p><h5>피해야 할 환경</h5><p>'+escapeHtml(item.unfavorableMarketKo)+'</p><h5>실패·반례</h5>'+list(item.failureModesKo)+'<h5>다른 방법과 충돌할 때</h5><p>'+escapeHtml(item.conflictInterpretationKo)+'</p></details><div class="masters-block"><h5>이 분야의 대표 대가</h5><div class="master-grid">'+masters.map(function(master){return'<article class="master-card"><b>'+escapeHtml(master.name)+'</b><p>'+escapeHtml(master.roleKo)+'</p>'+sourceLink(master)+'</article>';}).join('')+'</div></div><article class="case-card"><span class="case-label">대표 수익·연구 사례</span><h5>'+escapeHtml(caseStudy.titleKo)+'</h5><p>'+escapeHtml(caseStudy.summaryKo)+'</p><p><b>관찰된 결과</b> · '+escapeHtml(caseStudy.outcomeKo)+'</p><p><b>사용자가 기억할 점</b> · '+escapeHtml(caseStudy.lessonKo)+'</p>'+sourceLink(caseStudy)+'</article><p class="education-caution"><b>오해 방지</b> · '+escapeHtml(item.cautionKo)+'</p><p class="content-review">콘텐츠 검토 '+escapeHtml(item.reviewedAt)+' · 다음 검토 '+escapeHtml(item.nextReviewAt)+'</p></section>';}
  function reportHtml(value){var signal=value.signal,rule=value.method;return'<div class="report-title"><div><span class="pill">합성자료 · '+escapeHtml(rule.family)+'</span><h3>'+escapeHtml(value.identity.ticker)+' · '+escapeHtml(value.identity.name)+'</h3><p>'+escapeHtml(rule['name'+(local.locale==='ko'?'Ko':local.locale==='en'?'En':'Ja')]||rule.nameKo)+' · '+escapeHtml(value.target.horizon)+' · 기준일 '+escapeHtml(value.target.asOf)+'</p></div><div class="report-score '+scoreClass(signal.label)+'"><b>'+signal.signalScore+'</b><span>합성 비교점수</span></div></div><section class="executive-summary"><h4>한 문장 결론</h4><p>'+escapeHtml(value.conclusion)+'</p></section><div class="report-meta"><span>백분위 '+signal.percentile+'</span><span>표시 신뢰도 '+Math.round(signal.confidence*100)+'%</span><span>자료충족 '+Math.round(signal.dataSufficiency*100)+'%</span><span>'+escapeHtml(value.dataQuality.labelKo)+'</span></div><section><h4>점수의 의미와 자료 품질</h4><p>'+escapeHtml(value.scoreMeaning)+'</p><p>자료 상태: '+escapeHtml(value.dataQuality.state)+' · 신선도: '+escapeHtml(value.dataQuality.freshness)+' · 콘텐츠 검토: '+escapeHtml(value.dataQuality.reviewedAt)+'</p></section><section><h4>무엇을 평가하나</h4><p>'+escapeHtml(rule.descriptionKo)+'</p><p>'+escapeHtml(value.explanation)+'</p></section><section><h4>찬성 근거 3개</h4>'+list(value.positiveEvidence.slice(0,3))+'</section><section class="counter"><h4>반대 근거·한계</h4>'+list(value.counterEvidence.concat(value.dataWarnings))+'</section>'+educationHtml(value.education)+'<details><summary>입력값과 계산 보기</summary><dl class="input-grid">'+value.inputs.map(function(item){return'<div><dt>'+escapeHtml(item.name)+'</dt><dd>'+escapeHtml(item.value)+' '+escapeHtml(item.unit)+'</dd></div>';}).join('')+'</dl><code>'+escapeHtml(value.formulaTrace)+'</code></details><details><summary>자료 범위와 과거 성적</summary><p><b>실제 과거 성적은 제공하지 않습니다.</b> 이 보고서는 합성자료의 비교 결과만 보여줍니다.</p><p>실제 투자 판단에는 허가된 시장자료, 과거 시점 검증, 확률 보정과 별도 검토가 필요합니다.</p></details><section><h4>판단이 바뀌는 조건</h4>'+list(value.changeConditions)+'</section><section><h4>낙관·기준·비관 시나리오</h4>'+list(value.scenarios.map(function(item){return item.name+': '+item.condition;}))+'</section><section><h4>출처·검토 기록</h4><p>현재 수치 출처는 합성 고정자료이며 재배포 상태는 '+escapeHtml(value.licenseState)+'입니다. 방법론 역사 자료의 원출처는 위 교육 카드의 근거 링크에서 확인할 수 있습니다.</p></section><p class="disclaimer">'+escapeHtml(value.disclaimer)+'</p>';
  }
  function comparisonHtml(value){return'<details class="comparison-details"><summary>선택 방법 비교·민감도</summary><p>종합점수 <b>'+value.aggregation.score+'</b> · '+value.families+'개 계열 · 가중치 합 '+value.weightSum+'</p><div class="comparison-scroll"><table><thead><tr><th>방법</th><th>계열</th><th>점수</th><th>가중치</th><th>제외 영향</th></tr></thead><tbody>'+value.rows.map(function(item){return'<tr><th scope="row">'+escapeHtml(item.methodName)+'</th><td>'+escapeHtml(item.family)+'</td><td>'+item.signalScore+'</td><td>'+Math.round(item.weight*100)+'%</td><td>'+(item.sensitivityDelta==null?'—':(item.sensitivityDelta>0?'+':'')+item.sensitivityDelta)+'</td></tr>';}).join('')+'</tbody></table></div><p class="'+(value.minimumThreeFamiliesPassed?'positive':'counter')+'">'+(value.minimumThreeFamiliesPassed?'서로 다른 3개 이상 계열 조건을 통과했습니다.':'서로 다른 3개 이상 계열이 필요합니다.')+'</p>'+list(value.warnings)+'</details>';}
  function openReport(securityId,methodId){var horizon=el('scanHorizon').value,compatible=Scanner.compatibleMethods(horizon),selected=selectedMethods().filter(function(id){return compatible.some(function(rule){return rule.id===id;});}),chosen=methodId||selected[0]||(compatible[0]&&compatible[0].id);if(!chosen)return toast('이 기간에 사용할 수 있는 방법이 없습니다.');currentReport=Scanner.report(securityId,chosen,horizon,el('scanAsOf').value);var comparisonIds=selected.length?selected:[chosen],comparison=Scanner.compare(securityId,comparisonIds,horizon,el('scanAsOf').value),html=reportHtml(currentReport)+comparisonHtml(comparison),chips=compatible.map(function(rule){return'<button type="button" data-report-method="'+rule.id+'" class="chip '+(rule.id===chosen?'active':'')+'">'+escapeHtml(methodName(rule))+'</button>';}).join('');el('reportPanel').innerHTML=html;el('reportMethods').innerHTML=chips;el('mobileReportBody').innerHTML='<div id="mobileReportMethods" class="method-chips" aria-label="보고서 방법 선택">'+chips+'</div>'+html;[el('reportMethods'),el('mobileReportMethods')].filter(Boolean).forEach(function(container){container.querySelectorAll('[data-report-method]').forEach(function(button){button.addEventListener('click',function(){openReport(securityId,button.getAttribute('data-report-method'));});});});local.recentReports=[{securityId:securityId,methodId:chosen,horizon:horizon,asOf:currentReport.target.asOf,ticker:currentReport.identity.ticker,name:currentReport.identity.name}].concat(local.recentReports.filter(function(item){return item.securityId!==securityId||item.methodId!==chosen;})).slice(0,20);persist();renderRecent();if(matchMedia('(max-width: 899px)').matches)route('reports');}
  function run(){if(!selectionSummary()){el('resultStatus').textContent='검사를 시작하지 않았습니다. 서로 다른 3개 계열에서 방법을 하나씩 선택하거나 예상기간을 바꾸세요.';return;}el('resultStatus').textContent='합성 후보를 계산하고 있습니다. 선택한 조건을 같은 고정 규칙으로 적용합니다.';try{showAllResults=false;compareIds=[];currentResult=Scanner.scan(options());renderResults(currentResult);if(currentResult.rows[0]&&!matchMedia('(max-width: 899px)').matches)openReport(currentResult.rows[0].securityId);if(!currentResult.rows.length){currentReport=null;el('reportMethods').innerHTML='';el('reportPanel').innerHTML='<p class="empty"><b>조건에 맞는 합성 후보가 없습니다.</b><span>검색어를 지우거나 최소 점수를 낮추고 방법과 예상기간을 확인하세요.</span></p>';el('mobileReportBody').innerHTML=el('reportPanel').innerHTML;}toast('합성 고정자료 검사가 완료됐습니다.');}catch(error){el('resultStatus').textContent='검사를 완료하지 못했습니다. 선택한 방법과 예상기간을 확인하세요. 오류 코드: '+error.message;toast('조건을 확인한 뒤 다시 실행하세요.');}}
  function renderSaved(){el('savedScans').innerHTML=local.savedScans.map(function(item){return'<li><button type="button" data-saved="'+item.id+'"><b>'+escapeHtml(item.name)+'</b><small>'+item.filters.market+' · '+item.filters.horizon+' · '+item.filters.methodIds.length+'개 방법</small></button><button type="button" class="icon-button" aria-label="'+escapeHtml(item.name)+' 삭제" data-delete-saved="'+item.id+'">×</button></li>';}).join('')||'<li class="empty">저장한 검사가 없습니다.</li>';el('savedScans').querySelectorAll('[data-saved]').forEach(function(button){button.addEventListener('click',function(){var found=local.savedScans.find(function(item){return item.id===button.getAttribute('data-saved');});if(!found)return;el('scanMarket').value=found.filters.market;el('scanHorizon').value=found.filters.horizon;el('scanSector').value=found.filters.sector;el('scanMinScore').value=found.filters.minScore;el('scanQuery').value=found.filters.query||'';renderMethods();Array.from(document.querySelectorAll('input[name="methodId"]')).forEach(function(box){box.checked=found.filters.methodIds.indexOf(box.value)>=0;});route('scan');run();});});el('savedScans').querySelectorAll('[data-delete-saved]').forEach(function(button){button.addEventListener('click',function(){local.savedScans=local.savedScans.filter(function(item){return item.id!==button.getAttribute('data-delete-saved');});persist();renderSaved();});});}
  function renderWatchlist(){var rows=local.watchlist.map(function(id){return Scanner.universe().find(function(item){return item.securityId===id;});}).filter(Boolean);el('watchlistItems').innerHTML=rows.map(function(item){return'<li><button type="button" data-watch-report="'+item.securityId+'"><b>'+escapeHtml(item.ticker)+' · '+escapeHtml(item.name)+'</b><small>'+item.market+' · '+escapeHtml(item.sector)+'</small></button><button type="button" class="icon-button" aria-label="'+escapeHtml(item.ticker)+' 관심 삭제" data-watch-delete="'+item.securityId+'">×</button></li>';}).join('')||'<li class="empty">관심 종목이 없습니다.</li>';el('watchlistItems').querySelectorAll('[data-watch-report]').forEach(function(button){button.addEventListener('click',function(){openReport(button.getAttribute('data-watch-report'));});});el('watchlistItems').querySelectorAll('[data-watch-delete]').forEach(function(button){button.addEventListener('click',function(){local.watchlist=local.watchlist.filter(function(id){return id!==button.getAttribute('data-watch-delete');});persist();refreshLocalViews();});});}
  function renderRecent(){el('recentReports').innerHTML=local.recentReports.map(function(item){return'<li><button type="button" data-recent-security="'+item.securityId+'" data-recent-method="'+item.methodId+'"><b>'+escapeHtml(item.ticker)+' · '+escapeHtml(item.name)+'</b><small>'+escapeHtml(item.methodId)+' · '+escapeHtml(item.horizon)+' · '+escapeHtml(item.asOf)+'</small></button></li>';}).join('')||'<li class="empty">최근 보고서가 없습니다.</li>';el('recentReports').querySelectorAll('[data-recent-security]').forEach(function(button){button.addEventListener('click',function(){el('scanHorizon').value=button.parentNode.querySelector('small').textContent.split(' · ')[1]||'3M';renderMethods();openReport(button.getAttribute('data-recent-security'),button.getAttribute('data-recent-method'));});});}
  function legacySource(){for(var i=0;i<LEGACY_KEYS.length;i++){var raw=localStorage.getItem(LEGACY_KEYS[i]);if(raw){try{return{key:LEGACY_KEYS[i],data:JSON.parse(raw)};}catch(error){throw new Error('LEGACY_JSON_INVALID');}}}return null;}
